def check_p_a(a):
    target = 12 * a + 1
    if target <= 1:
        return None

    # Check perfect powers for p^a = target
    # We only need to check if target is an a-th power of an integer p >= 2

    # Estimate p: p = target**(1/a)
    import math
    try:
        p_float = target**(1/a)
        p_int = round(p_float)
    except OverflowError:
        return None # Target too large

    # Check integers near the estimated value
    for p in range(max(2, p_int - 2), p_int + 3):
        if p**a == target:
            if p > 1:
                # Check if p is prime
                def is_prime(k):
                    if k <= 1: return False
                    if k <= 3: return True
                    if k % 2 == 0 or k % 3 == 0: return False
                    i = 5
                    while i * i <= k:
                        if k % i == 0 or k % (i + 2) == 0:
                            return False
                        i += 6
                    return True

                if is_prime(p):
                    return (p, a)
    return None

